def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opp_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    urgent_opp_bids.append(bid)

    if not alive_opponents:
        return float(min(budget, 18.0))

    total_players = 1 + len(alive_opponents)
    expected_share = float(supply) / float(total_players)
    water_tight = expected_share < WATER_REQ

    sorted_bids = sorted(prev_bids)
    highest_prev = sorted_bids[-1] if sorted_bids else 0.0
    second_prev = sorted_bids[-2] if len(sorted_bids) >= 2 else highest_prev
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    urgent_prev = max(urgent_opp_bids) if urgent_opp_bids else 0.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2
    if day >= 8:
        danger += 1

    if water_tight:
        if danger >= 5:
            target = max(highest_prev + 2.0, 110.0)
        elif danger >= 3:
            target = max(second_prev + 2.0, avg_prev + 1.5, 88.0)
        else:
            if highest_prev >= 120.0:
                target = 22.0
            elif highest_prev >= 100.0:
                target = 36.0
            else:
                target = max(42.0, avg_prev * 0.55)
    else:
        if danger >= 5:
            target = max(urgent_prev + 2.0, avg_prev + 1.0, 72.0)
        elif danger >= 3:
            target = max(54.0, avg_prev * 0.65)
        else:
            if highest_prev >= 110.0:
                target = 18.0
            else:
                target = max(28.0, avg_prev * 0.4)

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 70.0 * (10 - day) * 0.18
    max_affordable = max(0.0, budget - reserve_floor)

    if danger >= 5:
        cap = min(budget, max(max_affordable, budget * 0.9))
    elif danger >= 3:
        cap = min(budget, max(max_affordable, budget * 0.65))
    else:
        cap = min(budget, max(max_affordable, budget * 0.35))

    bid = min(target, cap)

    if hp <= 1 or no_water_days >= 2:
        bid = min(budget, max(bid, highest_prev + 3.0, 118.0))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = float(budget)

    return float(round(bid, 2))

