def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_strong_bids = []
    yesterday_all_bids = []

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_all_bids.append(prev['bid'])
            # Consider an opponent "strong" if they have a significantly high budget AND previously bid high
            if opp['budget'] > DAILY_SALARY * 5 and prev['bid'] > DAILY_SALARY * 1.0:
                yesterday_strong_bids.append(prev['bid'])

    base_competitive_bid = DAILY_SALARY * 1.2 # Default strong bid

    if yesterday_strong_bids:
        highest_strong_bid = max(yesterday_strong_bids)
        base_competitive_bid = max(base_competitive_bid, highest_strong_bid + 2.0)
    elif yesterday_all_bids:
        average_all_bids = sum(yesterday_all_bids) / len(yesterday_all_bids)
        base_competitive_bid = max(base_competitive_bid, average_all_bids * 1.1)

    my_bid = base_competitive_bid
    if my_status['hp'] <= 2:
        my_bid = max(my_bid, DAILY_SALARY * 1.8)
    elif my_status['hp'] <= 4:
        my_bid = max(my_bid, DAILY_SALARY * 1.5)

    total_water_needed_by_players = WATER_REQ 
    for opp in alive_opponents:
        total_water_needed_by_players += opp['water_requirement']

    if day_context['supply'] < total_water_needed_by_players:
        my_bid *= 1.15
    elif day_context['supply'] >= total_water_needed_by_players + WATER_REQ:
        my_bid *= 0.95

    final_bid = min(my_status['budget'], my_bid)

    final_bid = max(final_bid, DAILY_SALARY * 0.9)

    if day_context['day'] == EPISODE_DAYS:
        return my_status['budget']

    final_bid = min(final_bid, DAILY_SALARY * 2.0)

    return max(0.0, final_bid)
